/**
 * Childcare price inflation versus parent wages (2026).
 *
 * Core question: How did childcare prices inflate relative to the wages of
 * families who pay them, and which metros price out median earners?
 *
 * Perimeter: BLS CPI-U day care and preschool (CUUR0000SEEB03, NSA); BLS CES
 * average hourly earnings of all private employees (CES0500000003); CPI-U all
 * items (CUUR0000SA0) as a general-price comparator; Child Care Aware of America
 * 2024???2025 Price & Supply state/metro price levels; HHS 7% of household income
 * affordability benchmark for subsidized-care copays (used as a reference
 * threshold for market prices ??? not a statutory cap on private tuition).
 *
 * Headline: From Jan 2022 to mid-2026, day-care CPI rose ~20% while private
 * average hourly earnings rose ~17% ??? a ~3-point cumulative lead for childcare
 * prices ??? and in every large metro in this panel, center infant care still
 * consumes well above the 7% HHS affordability benchmark of median household income.
 */

export type Confidence = "disclosed" | "estimated" | "modeled";

export const SOURCE_NOTE =
  "BLS CPI-U day care and preschool (CUUR0000SEEB03, NSA) and CPI-U all items (CUUR0000SA0); BLS CES average hourly earnings, all private employees (CES0500000003). Child Care Aware of America Child Care in America: 2024 Price & Supply and 2025 Price & Supply reports for national averages and state infant-center price levels. Metro infant-center prices and median household incomes blend CCAoA state sheets with ACS/BLS metro income anchors ??? shares are desk calculations. HHS 7% affordability benchmark applies to subsidized copays under recent federal rules; market prices are compared to that reference, not regulated by it. Index ratios and wage-gap points are desk math on the cited series.";

export const SOURCES = [
  {
    label: "BLS ??? CPI day care and preschool (CUUR0000SEEB03)",
    url: "https://data.bls.gov/timeseries/CUUR0000SEEB03",
  },
  {
    label: "BLS ??? Average hourly earnings, all private (CES0500000003)",
    url: "https://fred.stlouisfed.org/series/CES0500000003",
  },
  {
    label: "BLS ??? CPI-U all items (CUUR0000SA0)",
    url: "https://fred.stlouisfed.org/series/CPIAUCSL",
  },
  {
    label: "Child Care Aware of America ??? 2025 Price & Supply",
    url: "https://info.childcareaware.org/price-and-supply-2025",
  },
  {
    label: "HHS / OPRE ??? child care price and affordability research",
    url: "https://www.acf.hhs.gov/opre",
  },
] as const;

export const HEADLINE = {
  /** CUUR0000SEEB03 Jan 2022 ??? Jul 2026 cumulative % */
  childcareCumulPct2022to2026: 20.4,
  /** CES AHE Jan 2022 ??? Jul 2026 cumulative % */
  wageCumulPct2022to2026: 16.9,
  /** childcare lead over wages, percentage points */
  childcareLeadPts: 3.5,
  /** CCAoA 2025 national average annual child care price ($) */
  nationalAvgPriceUsd: 13184,
  /** share of dual-earner median income (CCAoA 2025) */
  dualEarnerSharePct: 10,
  /** share of single-parent median income (CCAoA 2025) */
  singleParentSharePct: 33,
  /** HHS affordability benchmark (%) */
  hhsAffordabilityPct: 7,
  /** metros in panel above HHS 7% on infant-center / median HH income */
  metrosAboveHhs: 12,
  confidence: "disclosed" as Confidence,
};

