  { month: "2024-07", label: "Jul 24", childcareCumulPct: 12.8, wageCumulPct: 11.0, cpiAllCumulPct: 10.4, confidence: "disclosed" },
  { month: "2025-01", label: "Jan 25", childcareCumulPct: 17.3, wageCumulPct: 13.4, cpiAllCumulPct: 11.8, confidence: "disclosed" },
  { month: "2025-07", label: "Jul 25", childcareCumulPct: 19.2, wageCumulPct: 15.4, cpiAllCumulPct: 13.0, confidence: "disclosed" },
  { month: "2026-01", label: "Jan 26", childcareCumulPct: 19.1, wageCumulPct: 17.6, cpiAllCumulPct: 14.1, confidence: "disclosed" },
  { month: "2026-07", label: "Jul 26", childcareCumulPct: 20.4, wageCumulPct: 16.9, cpiAllCumulPct: 14.8, confidence: "estimated" },
];

export type HouseholdType = "dual" | "single";

/** National price burden by household type (CCAoA 2025) */
export type BurdenRow = {
  household: HouseholdType;
  label: string;
  shareOfMedianIncomePct: number;
  hhsBenchmarkPct: number;
  /** how many ?? the HHS 7% benchmark */
  multipleOfHhs: number;
  confidence: Confidence;
};

export const NATIONAL_BURDEN: BurdenRow[] = [
  { household: "dual", label: "Married / dual-earner", shareOfMedianIncomePct: 10, hhsBenchmarkPct: 7, multipleOfHhs: 1.43, confidence: "disclosed" },
  { household: "single", label: "Single-parent", shareOfMedianIncomePct: 33, hhsBenchmarkPct: 7, multipleOfHhs: 4.71, confidence: "disclosed" },
];

export type Region =
  | "Northeast"
  | "South"
  | "Midwest"
  | "West";

/** Metro infant-center price vs median household income */
export type MetroAffordabilityRow = {
  metro: string;
  short: string;
  region: Region;
  infantCenterUsd: number;
  medianHhIncomeUsd: number;
  /** infant center / median HH income ?? 100 */
  sharePct: number;
  /** sharePct ??? 7 */
  aboveHhsPts: number;
  pricesOutMedian: boolean;
  confidence: Confidence;
};

/**
 * Infant center prices from CCAoA state sheets and metro compilations;
 * median HH incomes from ACS 1-year / BLS metro anchors (2023???2024 vintage,
 * carried forward). Shares are desk calculations. "Prices out" = share > 15%
 * of median HH income (more than 2?? the HHS 7% reference).
 */
export const METRO_AFFORDABILITY: MetroAffordabilityRow[] = [
  { metro: "New York???Newark???Jersey City", short: "NYC", region: "Northeast", infantCenterUsd: 22100, medianHhIncomeUsd: 84500, sharePct: 26.2, aboveHhsPts: 19.2, pricesOutMedian: true, confidence: "estimated" },
  { metro: "Boston???Cambridge???Newton", short: "Boston", region: "Northeast", infantCenterUsd: 24600, medianHhIncomeUsd: 108200, sharePct: 22.7, aboveHhsPts: 15.7, pricesOutMedian: true, confidence: "estimated" },
  { metro: "San Francisco???Oakland???Berkeley", short: "SF Bay", region: "West", infantCenterUsd: 23800, medianHhIncomeUsd: 128400, sharePct: 18.5, aboveHhsPts: 11.5, pricesOutMedian: true, confidence: "estimated" },
  { metro: "Seattle???Tacoma???Bellevue", short: "Seattle", region: "West", infantCenterUsd: 19800, medianHhIncomeUsd: 106500, sharePct: 18.6, aboveHhsPts: 11.6, pricesOutMedian: true, confidence: "estimated" },
  { metro: "Washington???Arlington???Alexandria", short: "DC", region: "South", infantCenterUsd: 19500, medianHhIncomeUsd: 127300, sharePct: 15.3, aboveHhsPts: 8.3, pricesOutMedian: true, confidence: "estimated" },
  { metro: "Denver???Aurora???Lakewood", short: "Denver", region: "West", infantCenterUsd: 17600, medianHhIncomeUsd: 96800, sharePct: 18.2, aboveHhsPts: 11.2, pricesOutMedian: true, confidence: "estimated" },
  { metro: "Chicago???Naperville???Elgin", short: "Chicago", region: "Midwest", infantCenterUsd: 16400, medianHhIncomeUsd: 81200, sharePct: 20.2, aboveHhsPts: 13.2, pricesOutMedian: true, confidence: "estimated" },
  { metro: "Minneapolis???St. Paul???Bloomington", short: "MSP", region: "Midwest", infantCenterUsd: 17200, medianHhIncomeUsd: 91400, sharePct: 18.8, aboveHhsPts: 11.8, pricesOutMedian: true, confidence: "estimated" },
  { metro: "Miami???Fort Lauderdale???Pompano Beach", short: "Miami", region: "South", infantCenterUsd: 12400, medianHhIncomeUsd: 69200, sharePct: 17.9, aboveHhsPts: 10.9, pricesOutMedian: true, confidence: "estimated" },
  { metro: "Atlanta???Sandy Springs???Alpharetta", short: "Atlanta", region: "South", infantCenterUsd: 12100, medianHhIncomeUsd: 78400, sharePct: 15.4, aboveHhsPts: 8.4, pricesOutMedian: true, confidence: "estimated" },
  { metro: "Dallas???Fort Worth???Arlington", short: "Dallas", region: "South", infantCenterUsd: 12800, medianHhIncomeUsd: 81200, sharePct: 15.8, aboveHhsPts: 8.8, pricesOutMedian: true, confidence: "estimated" },
  { metro: "Phoenix???Mesa???Chandler", short: "Phoenix", region: "West", infantCenterUsd: 11200, medianHhIncomeUsd: 77800, sharePct: 14.4, aboveHhsPts: 7.4, pricesOutMedian: false, confidence: "estimated" },
];

/** Age-group national center prices (CCAoA 2025 Method blend) */
export type AgePriceRow = {
  ageGroup: string;
  centerUsd: number;
  fccHomeUsd: number;
  confidence: Confidence;
};

export const AGE_PRICES: AgePriceRow[] = [
  { ageGroup: "Infant", centerUsd: 15636, fccHomeUsd: 11673, confidence: "disclosed" },
  { ageGroup: "4-year-old", centerUsd: 12555, fccHomeUsd: 10572, confidence: "disclosed" },
];

/** Episode / regime markers for the narrative ladder */
export type RegimeRow = {
  id: string;
  label: string;
  window: string;
  childcareVsWage: string;
  note: string;
};

export const REGIMES: RegimeRow[] = [
  {
    id: "pre-covid",
    label: "Pre-COVID crawl",
    window: "2015???2019",
    childcareVsWage: "Roughly matched",
    note: "Day-care CPI and private AHE both rose ~10???12% over the window; the wage index stayed slightly ahead.",
  },
  {
    id: "composition",
    label: "Composition spike",
    window: "2020???2021",
    childcareVsWage: "Wages surged on mix",
    note: "CES AHE jumped as lower-wage hours disappeared; day-care CPI barely moved while centers closed and reopened.",
  },
  {
    id: "catch-up",
    label: "Childcare catch-up",
    window: "2022???2025",
    childcareVsWage: "Day-care CPI leads YoY",
    note: "Staffing shortages and wage pass-through pushed day-care CPI into a sustained 5%+ YoY band while AHE decelerated toward ~4%.",
  },
  {
    id: "levels",
    label: "Level problem",
    window: "2025???2026",
    childcareVsWage: "Inflation gap narrows; levels bite",
    note: "YoY gaps compress, but metro infant-center tuition still takes 14???26% of median household income ??? far above the 7% HHS reference.",
  },
];

export function fmtPct(n: number, digits = 1): string {
  return `${n.toFixed(digits)}%`;
}

export function fmtUsd(n: number): string {
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
    maximumFractionDigits: 0,
  }).format(n);
}

export function fmtPts(n: number, digits = 1): string {
  const sign = n > 0 ? "+" : "";
  return `${sign}${n.toFixed(digits)} pts`;
}

