args.streamContent:
"use client";

import { useMemo, useState } from "react";
import {
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Legend,
  Line,
  LineChart,
  ReferenceLine,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  ANNUAL_INDEX,
  CUMULATIVE_SINCE_2022,
  HEADLINE,
  METRO_AFFORDABILITY,
  MONTHLY_YOY,
  NATIONAL_BURDEN,
  REGIMES,
  SOURCE_NOTE,
  fmtPct,
  fmtUsd,
  type Region,
} from "@/data/childcare-price-inflation-versus-wages-2026-data";

// viz-types: cumulative dual-line, YoY gap bars, metro horizontal bars, price-income scatter | layout: default

type ViewId = "race" | "yoy" | "metros" | "scatter" | "burden";
type RegionFilter = "all" | Region;
type IndexMode = "cumulative" | "annual";

const NAVY = "#0f172a";
const TEAL = "#0f766e";
const AMBER = "#d97706";
const ROSE = "#be123c";
const SLATE = "#64748b";
const SKY = "#0284c7";

const REGION_COLORS: Record<Region, string> = {
  Northeast: ROSE,
  South: AMBER,
  Midwest: SKY,
  West: TEAL,
};

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle ? <p className="mt-1 text-sm text-slate-500">{subtitle}</p> : null}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((opt) => {
          const active = opt.id === value;
          return (
            <button
              key={opt.id}
              type="button"
              onClick={() => onChange(opt.id)}
              className={`rounded-md px-2.5 py-1 text-xs font-medium transition-colors ${
                active
                  ? "bg-slate-900 text-white"
                  : "text-slate-600 hover:bg-slate-50"
              }`}
            >
              {opt.label}
            </button>
          );
        })}
      </div>
    </div>
  );
}

export function ChildcarePriceInflationVersusWages2026Dashboard() {
  const [view, setView] = useState<ViewId>("race");
  const [region, setRegion] = useState<RegionFilter>("all");
  const [indexMode, setIndexMode] = useState<IndexMode>("cumulative");

  const metros = useMemo(() => {
    const rows =
      region === "all"
        ? METRO_AFFORDABILITY
        : METRO_AFFORDABILITY.filter((m) => m.region === region);
    return [...rows].sort((a, b) => b.sharePct - a.sharePct);
  }, [region]);

  const pricedOutCount = metros.filter((m) => m.pricesOutMedian).length;

  return (
    <div className="space-y-6">
      <div className="rounded-xl border border-slate-200 bg-gradient-to-br from-slate-50 to-white p-5 sm:p-6">
        <p className="text-xs font-semibold uppercase tracking-wide text-teal-800">
          Childcare prices vs parent wages
        </p>
        <p className="mt-2 text-2xl font-bold tracking-tight text-slate-900 sm:text-3xl">
          Day-care CPI led wages by {HEADLINE.childcareLeadPts} pts since 2022
        </p>
        <p className="mt-2 max-w-3xl text-sm text-slate-600">
          From early 2022 through mid-2026, BLS day-care and preschool prices rose{" "}
          {fmtPct(HEADLINE.childcareCumulPct2022to2026)} while private average hourly
          earnings rose {fmtPct(HEADLINE.wageCumulPct2022to2026)}. National averages
          still hide the level problem: center infant care takes{" "}
          {HEADLINE.dualEarnerSharePct}% of dual-earner median income and{" "}
          {HEADLINE.singleParentSharePct}% for single parents ??? versus a {HEADLINE.hhsAffordabilityPct}%
          HHS reference.
        </p>
        <div className="mt-4 flex flex-wrap gap-4 text-sm">
          <div>
            <span className="font-semibold text-slate-900">
              {fmtPct(HEADLINE.childcareCumulPct2022to2026, 1)}
            </span>
            <span className="text-slate-500"> day-care CPI</span>
          </div>
          <div>
            <span className="font-semibold text-slate-900">
              {fmtPct(HEADLINE.wageCumulPct2022to2026, 1)}
            </span>
            <span className="text-slate-500"> private AHE</span>
          </div>
          <div>
            <span className="font-semibold text-slate-900">
              {HEADLINE.metrosAboveHhs}/{METRO_AFFORDABILITY.length}
            </span>
            <span className="text-slate-500"> metros above 7% HHS</span>
          </div>
        </div>
      </div>

      <div className="flex flex-col gap-3 sm:flex-row sm:flex-wrap sm:items-center sm:justify-between">
        <ToggleGroup
          label="Panel"
          value={view}
          onChange={setView}
          options={[
            { id: "race", label: "Price race" },
            { id: "yoy", label: "YoY gap" },
            { id: "metros", label: "Metro shares" },
            { id: "scatter", label: "Price ?? income" },
            { id: "burden", label: "Household burden" },
          ]}
        />
        {view === "race" ? (
          <ToggleGroup
            label="Index"
            value={indexMode}
            onChange={setIndexMode}
            options={[
              { id: "cumulative", label: "Since Jan 2022" },
              { id: "annual", label: "2015 = 100" },
            ]}
          />
        ) : null}
        {view === "metros" || view === "scatter" ? (
          <ToggleGroup
            label="Region"
            value={region}
            onChange={setRegion}
            options={[
              { id: "all", label: "All" },
              { id: "Northeast", label: "NE" },
              { id: "South", label: "South" },
              { id: "Midwest", label: "MW" },
              { id: "West", label: "West" },
            ]}
          />
        ) : null}
      </div>

      {view === "race" ? (
        <ChartCard
          title={
            indexMode === "cumulative"
              ? "Cumulative change since January 2022"
              : "Rebased indices (2015 = 100)"
          }
          subtitle="Day-care CPI vs private average hourly earnings vs all-items CPI"
        >
          <div className="h-[360px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              {indexMode === "cumulative" ? (
                <ComposedChart data={CUMULATIVE_SINCE_2022} margin={{ top: 8, right: 12, left: 0, bottom: 0 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="label" tick={{ fontSize: 11 }} />
                  <YAxis tick={{ fontSize: 11 }} unit="%" />
                  <Tooltip />
                  <Legend />
                  <Line type="monotone" dataKey="childcareCumulPct" name="Day-care CPI" stroke={TEAL} strokeWidth={2.5} dot={false} />
                  <Line type="monotone" dataKey="wageCumulPct" name="Private AHE" stroke={NAVY} strokeWidth={2.5} dot={false} />
                  <Line type="monotone" dataKey="cpiAllCumulPct" name="CPI all items" stroke={SLATE} strokeWidth={1.5} strokeDasharray="4 4" dot={false} />
                </ComposedChart>
              ) : (
                <LineChart data={ANNUAL_INDEX} margin={{ top: 8, right: 12, left: 0, bottom: 0 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="year" tick={{ fontSize: 11 }} />
                  <YAxis tick={{ fontSize: 11 }} domain={[95, "auto"]} />
                  <Tooltip />
                  <Legend />
                  <Line type="monotone" dataKey="childcareIdx" name="Day-care CPI" stroke={TEAL} strokeWidth={2.5} dot />
                  <Line type="monotone" dataKey="wageIdx" name="Private AHE" stroke={NAVY} strokeWidth={2.5} dot />
                  <Line type="monotone" dataKey="cpiAllIdx" name="CPI all items" stroke={SLATE} strokeWidth={1.5} strokeDasharray="4 4" dot={false} />
                </LineChart>
              )}
            </ResponsiveContainer>
          </div>
          <p className="mt-3 text-xs text-slate-500">
            On a 2015=100 rebase, wages still sit ahead of day-care CPI because of the 2020???21
            composition spike in CES earnings. The post-2022 cumulative path is the cleaner
            read of the recent catch-up.
          </p>
        </ChartCard>
      ) : null}

      {view === "yoy" ? (
        <ChartCard
          title="Year-over-year: day-care CPI minus wage growth"
          subtitle="Positive bars = childcare prices inflating faster than private AHE"
        >
          <div className="h-[360px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={MONTHLY_YOY} margin={{ top: 8, right: 12, left: 0, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis dataKey="label" tick={{ fontSize: 10 }} interval={1} />
                <YAxis tick={{ fontSize: 11 }} unit=" pts" />
                <Tooltip />
                <ReferenceLine y={0} stroke={SLATE} />
                <Bar dataKey="gapPts" name="Childcare ??? wage YoY (pts)">
                  {MONTHLY_YOY.map((row) => (
                    <Cell
                      key={row.month}
                      fill={row.gapPts >= 0 ? TEAL : AMBER}
                    />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
          <div className="mt-4 grid gap-2 sm:grid-cols-2">
            {REGIMES.map((r) => (
              <div
                key={r.id}
                className="rounded-lg border border-slate-100 bg-slate-50 px-3 py-2"
              >
                <p className="text-xs font-semibold text-slate-900">
                  {r.label}{" "}
                  <span className="font-normal text-slate-500">({r.window})</span>
                </p>
                <p className="text-xs text-teal-800">{r.childcareVsWage}</p>
                <p className="mt-1 text-xs text-slate-600">{r.note}</p>
              </div>
            ))}
          </div>
        </ChartCard>
      ) : null}

      {view === "metros" ? (
        <ChartCard
          title="Infant center care as % of median household income"
          subtitle={`${pricedOutCount} of ${metros.length} shown metros exceed 15% (desk ???prices out??? cut); HHS reference is 7%`}
        >
          <div className="h-[420px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart
                layout="vertical"
                data={metros}
                margin={{ top: 8, right: 24, left: 8, bottom: 0 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" horizontal={false} />
                <XAxis type="number" tick={{ fontSize: 11 }} unit="%" domain={[0, 30]} />
                <YAxis type="category" dataKey="short" width={56} tick={{ fontSize: 11 }} />
                <Tooltip
                  formatter={(value) =>
                    typeof value === "number" ? fmtPct(value) : String(value ?? "")
                  }
                  labelFormatter={(_, payload) => {
                    const row = payload?.[0]?.payload as
                      | (typeof metros)[number]
                      | undefined;
                    return row ? row.metro : "";
                  }}
                />
                <ReferenceLine x={7} stroke={ROSE} strokeDasharray="4 4" label={{ value: "HHS 7%", fill: ROSE, fontSize: 11 }} />
                <ReferenceLine x={15} stroke={AMBER} strokeDasharray="3 3" label={{ value: "15%", fill: AMBER, fontSize: 11 }} />
                <Bar dataKey="sharePct" name="% of median HH income" radius={[0, 4, 4, 0]}>
                  {metros.map((m) => (
                    <Cell key={m.short} fill={REGION_COLORS[m.region]} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      ) : null}

      {view === "scatter" ? (
        <ChartCard
          title="Metro infant-center price vs median household income"
          subtitle="Bubble size ??? income share; dashed line marks a 7% HHS-affordability ray"
        >
          <div className="h-[380px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <ScatterChart margin={{ top: 12, right: 16, left: 8, bottom: 8 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                  type="number"
                  dataKey="medianHhIncomeUsd"
                  name="Median HH income"
                  tick={{ fontSize: 11 }}
                  tickFormatter={(v) => `$${Math.round(Number(v) / 1000)}k`}
                  domain={[60000, 140000]}
                />
                <YAxis
                  type="number"
                  dataKey="infantCenterUsd"
                  name="Infant center $"
                  tick={{ fontSize: 11 }}
                  tickFormatter={(v) => `$${Math.round(Number(v) / 1000)}k`}
                  domain={[10000, 26000]}
                />
                <ZAxis type="number" dataKey="sharePct" range={[60, 280]} />
                <Tooltip
                  cursor={{ strokeDasharray: "3 3" }}
                  formatter={(value, name) => {
                    if (name === "medianHhIncomeUsd" || name === "Median HH income")
                      return [fmtUsd(Number(value)), "Median HH income"];
                    if (name === "infantCenterUsd" || name === "Infant center $")
                      return [fmtUsd(Number(value)), "Infant center"];
                    return [String(value), String(name)];
                  }}
                  labelFormatter={(_, payload) => {
                    const row = payload?.[0]?.payload as
                      | (typeof metros)[number]
                      | undefined;
                    return row
                      ? `${row.short}: ${fmtPct(row.sharePct)} of median income`
                      : "";
                  }}
                />
                <Scatter name="Metros" data={metros}>
                  {metros.map((m) => (
                    <Cell key={m.short} fill={REGION_COLORS[m.region]} />
                  ))}
                </Scatter>
              </ScatterChart>
            </ResponsiveContainer>
          </div>
          <p className="mt-2 text-xs text-slate-500">
            A 7% ray would put a $100k-income metro near ${fmtUsd(7000)} infant tuition ???
            every bubble here sits well above that geometry.
          </p>
        </ChartCard>
      ) : null}

      {view === "burden" ? (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="National price vs median income"
            subtitle="CCAoA 2025 average child care price as share of family income"
          >
            <div className="h-[280px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={NATIONAL_BURDEN} margin={{ top: 8, right: 12, left: 0, bottom: 0 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="label" tick={{ fontSize: 11 }} />
                  <YAxis tick={{ fontSize: 11 }} unit="%" domain={[0, 40]} />
                  <Tooltip />
                  <ReferenceLine y={7} stroke={ROSE} strokeDasharray="4 4" />
