          <ToggleGroup
            label="Index"
            value={indexMode}
            onChange={setIndexMode}
            options={[
              { id: "cumulative", label: "Since Jan 2022" },
              { id: "annual", label: "2015 = 100" },
            ]}
          />
        ) : null}
        {view === "metros" || view === "scatter" ? (
          <ToggleGroup
            label="Region"
            value={region}
            onChange={setRegion}
            options={[
              { id: "all", label: "All" },
              { id: "Northeast", label: "NE" },
              { id: "South", label: "South" },
              { id: "Midwest", label: "MW" },
              { id: "West", label: "West" },
