                </p>
                <p className="text-xs text-teal-800">{r.childcareVsWage}</p>
                <p className="mt-1 text-xs text-slate-600">{r.note}</p>
              </div>
            ))}
          </div>
        </ChartCard>
      ) : null}

      {view === "metros" ? (
        <ChartCard
          title="Infant center care as % of median household income"
          subtitle={`${pricedOutCount} of ${metros.length} shown metros exceed 15% (desk ???prices out??? cut); HHS reference is 7%`}
        >
          <div className="h-[420px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart
                layout="vertical"
                data={metros}
                margin={{ top: 8, right: 24, left: 8, bottom: 0 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" horizontal={false} />
                <XAxis type="number" tick={{ fontSize: 11 }} unit="%" domain={[0, 30]} />
                <YAxis type="category" dataKey="short" width={56} tick={{ fontSize: 11 }} />
                <Tooltip
                  formatter={(value) =>
                    typeof value === "number" ? fmtPct(value) : String(value ?? "")
                  }
                  labelFormatter={(_, payload) => {
                    const row = payload?.[0]?.payload as
                      | (typeof metros)[number]
                      | undefined;
                    return row ? row.metro : "";
                  }}
                />
                <ReferenceLine x={7} stroke={ROSE} strokeDasharray="4 4" label={{ value: "HHS 7%", fill: ROSE, fontSize: 11 }} />
                <ReferenceLine x={15} stroke={AMBER} strokeDasharray="3 3" label={{ value: "15%", fill: AMBER, fontSize: 11 }} />
