/**
 * QA: childcare-price-inflation-versus-wages-2026
 * // viz-types: cumulative dual-line, YoY gap bars, metro horizontal bars, price-income scatter | layout: default
 * // smoke-marker: Day-care CPI led wages
 */
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { chromium } from "playwright";
import { startStaticServer, stopStaticServer } from "./lib/static-server.mjs";
import { auditVizInteractions } from "./lib/viz-interaction-qa.mjs";
import {
  ANNUAL_INDEX,
  CUMULATIVE_SINCE_2022,
  HEADLINE,
  METRO_AFFORDABILITY,
  MONTHLY_YOY,
  NATIONAL_BURDEN,
} from "../src/data/childcare-price-inflation-versus-wages-2026-data.ts";

assert.ok(HEADLINE.childcareCumulPct2022to2026 >= 19 && HEADLINE.childcareCumulPct2022to2026 <= 22);
assert.ok(HEADLINE.wageCumulPct2022to2026 >= 15 && HEADLINE.wageCumulPct2022to2026 <= 18);
assert.ok(HEADLINE.childcareLeadPts >= 3 && HEADLINE.childcareLeadPts <= 4);
assert.equal(HEADLINE.hhsAffordabilityPct, 7);
assert.ok(ANNUAL_INDEX.length >= 10);
assert.ok(CUMULATIVE_SINCE_2022.length >= 8);
assert.ok(MONTHLY_YOY.length >= 12);
assert.ok(METRO_AFFORDABILITY.length >= 10);
assert.ok(NATIONAL_BURDEN.length === 2);
assert.ok(METRO_AFFORDABILITY.every((m) => m.sharePct > HEADLINE.hhsAffordabilityPct));

const root = process.cwd();
const slug = "childcare-price-inflation-versus-wages-2026";
const markers = [
  "Day-care CPI led wages",
  "Cumulative change since January 2022",
];

async function clickBtn(page, name) {
  console.log(`??? click ${name}`);
  await page.locator("button", { hasText: name }).first().click({ timeout: 8000 });
  await page.waitForTimeout(200);
}

async function main() {
  const outDir = path.join(root, "out");
  if (!fs.existsSync(outDir)) {
    console.error("??? Missing out/ ??? run npm run build first");
    process.exit(1);
  }
  const port = Number(process.env.SMOKE_PORT || 4184);
  const server = await startStaticServer(outDir, port);
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  page.setDefaultTimeout(15000);
  try {
    await page.goto(`http://127.0.0.1:${port}/blog/${slug}.html`, {
      waitUntil: "domcontentloaded",
      timeout: 45000,
    });
    await page.waitForSelector(`[data-viz="${slug}"]`, { timeout: 20000 });
    for (const m of markers) {
      await page.getByText(m, { exact: false }).first().waitFor({ timeout: 20000 });
      console.log(`??? ${m}`);
    }
    await clickBtn(page, "YoY gap");
    await clickBtn(page, "Metro shares");
    await clickBtn(page, "NE");
    await clickBtn(page, "All");
    await clickBtn(page, "Price ?? income");
    await clickBtn(page, "Household burden");
    await clickBtn(page, "Price race");
    await clickBtn(page, "2015 = 100");
    await clickBtn(page, "Since Jan 2022");
    await auditVizInteractions(page, { slug, maxButtons: 14 });
    console.log("??? QA passed:", slug);
  } finally {
    await browser.close();
    await stopStaticServer(server);
  }
}

main().catch((err) => {
  console.error("??? QA failed:", err);
  process.exit(1);
});

